update_rule.pseudocode:
if t == 0:
  N = population_size
  if network_type == 'small_world':
    G = watts_strogatz_graph(N, k=avg_degree, p=small_world_rewiring_prob, seed=random_seed)
  else if network_type == 'erdos_renyi':
    p_conn = avg_degree / (N-1)
    G = erdos_renyi_graph(N, p_conn, seed=random_seed)
  node_neighbors = {i: list(G.neighbors(i)) for i in G.nodes}
  emit signal.network_edges = list(G.edges)
  emit signal.node_neighbors = node_neighbors
else:
  pass

mandate_status = (t >= policy_mandate_day) and (t < policy_lift_day)
# Spread awareness
for person in Persons:
  if mandate_status:
    if not person.policy_awareness:
      person.policy_awareness |= Bernoulli(policy_awareness_spread_rate)
emit signal.mandate_status = mandate_status
emit signal.policy_awareness_delta = average(change in policy_awareness)

if (t % max(1, int(1/messaging_frequency)) == 0):
  media_field = 0
  for outlet in MediaOutlets:
    msg = campaign_intensity * outlet.message_bias
    if Random() < outlet.misinformation_probability:
      msg -= message_effect_size  # misinformation reduces effect
    media_field += outlet.reach * msg
  emit signal.media_influence_field = media_field
else:
  emit signal.media_influence_field = 0

visits = {type: [] for type in ['workplace','school','retail','transit']}
contacts = []
compliance_by_type = {type: [] for type in visits}
for person in Persons:
  n_contacts = Poisson(person.daily_contacts_mean)
  # Sample location types based on mobility_profile
  loc_types = Multinomial(n_contacts, probs=person.mobility_profile)
  for lt, cnt in loc_types.items():
    for _ in range(cnt):
      loc = random_location_of_type(lt)
      visits[lt].append((person.id, loc.id))
      contacts.append((person.id, loc.id))
      compliance_by_type[lt].append(person.current_mask_use)
emit signal.visits_by_location_type = visits
emit signal.contacts = contacts
emit signal.compliance_by_location_type = {lt: mean(vals) if vals else 0 for lt, vals in compliance_by_type.items()}

actions = 0
if signal.mandate_status:
  for lt, visits in signal.visits_by_location_type.items():
    for (pid, lid) in visits:
      person = Persons[pid]
      loc = Locations[lid]
      if person.current_mask_use == 0:
        p_check = enforcement_probability * loc.enforcement_strength
        if Bernoulli(p_check):
          actions += 1
          person.policy_awareness = True
          # Record sanction memory (notified/fined)
          person._sanction_until = t + sanction_memory_days
emit signal.enforcement_actions_today = actions

for hh in Households:
  avg_att = mean(Persons[pid].attitude_toward_masks for pid in hh.members)
  for pid in hh.members:
    person = Persons[pid]
    person.attitude_toward_masks = clamp(person.attitude_toward_masks*(1-household_influence_weight) + household_influence_weight*avg_att, -1, 1)
emit signal.household_alignment = True
